      let body
      try {
        body = JSON.parse(responseText)
      } catch {
        throw new Error('Image relay returned invalid JSON (HTTP ' + response.status + ').')
      }
      if (!response.ok) {
        const message = String(body?.error?.message || body?.error || 'Request rejected').split(apiKey).join('[redacted]')
